cat > test/money.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert');
const { toCents } = require('../parse');
const { formatCents } = require('../format');
const { discountCents } = require('../discount');
const { invoice } = require('../invoice');

test('toCents is exact for prices that floating point multiplies badly', () => {
  assert.strictEqual(toCents('0.29'), 29);
  assert.strictEqual(toCents('1.15'), 115);
  assert.strictEqual(toCents('-0.50'), -50);
});

test('formatCents handles negatives', () => {
  assert.strictEqual(formatCents(-50), '-0.50');
  assert.strictEqual(formatCents(-1234), '-12.34');
  assert.strictEqual(formatCents(1234), '12.34');
  assert.strictEqual(formatCents(0), '0.00');
});

test('discountCents rounds to nearest cent', () => {
  assert.strictEqual(discountCents(1005, 10), 101); // 100.5 -> 101
  assert.strictEqual(discountCents(1000, 15), 150);
});

test('refund lines print correctly in an invoice', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Mug', price: '10.00', qty: 1 }, { name: 'Refund', price: '-0.50', qty: 1 }]),
    ['Mug: 10.00', 'Refund: -0.50', 'Total: 9.50']
  );
});

test('a cent-sensitive order totals correctly', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Pen', price: '0.29', qty: 3 }]),
    ['Pen: 0.87', 'Total: 0.87']
  );
});
EOF
